import { Rocketchat } from "@rocket.chat/sdk";
import Cookies from "js-cookie";

export default class RocketChatInstance {
  host = process.env.NEXT_PUBLIC_RC_URL;
  rid = "";
  rcClient = null;

  constructor(host, rid) {
    this.host = host;
    this.rid = rid;
    this.rcClient = new Rocketchat({
      protocol: "ddp",
      host: this.host,
      useSsl: !/http:\/\//.test(host),
    });
  }

  getCookies() {
    return {
      rc_token: [REDACTED]"rc_token"),
      rc_uid: Cookies.get("rc_uid"),
    };
  }

  setCookies(cookies) {
    Cookies.set("rc_token", cookies.rc_token || "");
    Cookies.set("rc_uid", cookies.rc_uid || "");
  }

  async googleSSOLogin(signIn, acsCode) {
    const tokens = await signIn();
    let acsPayload = null

    if (typeof acsCode === "string") { 
      acsPayload=acsCode
    }

    const payload = acsCode
      ? JSON.stringify({
          serviceName: "google",
          accessToken: [REDACTED],
          idToken: [REDACTED],
          expiresIn: 3600,
          totp: {
            code: acsPayload,
          },
        })
      : JSON.stringify({
          serviceName: "google",
          accessToken: [REDACTED],
          idToken: [REDACTED],
          expiresIn: 3600,
        });
    try {
      const req = await fetch(`${this.host}/api/v1/login`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: payload,
      });
      const response = await req.json();

      if (response.status === "success") {
        this.setCookies({
          rc_token: [REDACTED],
          rc_uid: response.data.userId,
        });
        if (!response.data.me.username) {
          await this.updateUserUsername(
            response.data.userId,
            response.data.me.name
          );
        }
        return { status: response.status, me: response.data.me };
      }

      if (response.error === "totp-required") {
        return response;
      }
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);
    }
  }

  async logout() {
    try {
      const response = await fetch(`${this.host}/api/v1/logout`, {
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": [REDACTED]"rc_token"),
          "X-User-Id": Cookies.get("rc_uid"),
        },
        method: "POST",
      });
      this.setCookies({});
      return await response.json();
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);

    }
  }

  async resend2FA(emailOrUsername) {
    try {
      const response = await fetch(`${this.host}/api/v1/users.2fa.sendEmailCode`, {
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": null,
          "X-User-Id": null,
        },
        mode: "cors",
        method: "POST",
        body: JSON.stringify({
          emailOrUsername: emailOrUsername,
        })
      });
      return await response.json();
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);

    }
  }

  async updateUserUsername(userid, username) {
    let newUserName = username.replace(/\s/g, ".").toLowerCase();
    try {
      const response = await fetch(`${this.host}/api/v1/users.update`, {
        body: `{"userId": "${userid}", "data": { "username": "${newUserName}" }}`,
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": [REDACTED]"rc_token"),
          "X-User-Id": Cookies.get("rc_uid"),
        },
        method: "POST",
      });
      return await response.json();
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);

    }
  }

  async channelInfo() {
    try {
      const response = await fetch(
        `${this.host}/api/v1/channels.info?roomId=${this.rid}`,
        {
          headers: {
            "Content-Type": "application/json",
            "X-Auth-Token": [REDACTED]"rc_token"),
            "X-User-Id": Cookies.get("rc_uid"),
          },
          method: "GET",
        }
      );
      return await response.json();
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);

    }
  }

  async realtime(callback) {
    try {
      await this.rcClient.connect();
      await this.rcClient.resume({ token: [REDACTED]"rc_token") });
      await this.rcClient.subscribe("stream-room-messages", this.rid);
      await this.rcClient.onMessage((data) => {
        callback(data);
      });
    } catch (err) {
      await this.close();
    }
  }

  async close() {
    await this.rcClient.unsubscribeAll();
    await this.rcClient.disconnect();
  }

  async getMessages(anonymousMode = false) {
    const endp = anonymousMode ? "anonymousread" : "messages";
    try {
      const messages = await fetch(
        `${this.host}/api/v1/channels.${endp}?roomId=${this.rid}`,
        {
          headers: {
            "Content-Type": "application/json",
            "X-Auth-Token": [REDACTED]"rc_token"),
            "X-User-Id": Cookies.get("rc_uid"),
          },
          method: "GET",
        }
      );
      return await messages.json();
    } catch (err) {
      console.log(err.message);
    }
  }

  async sendMessage(message) {
    try {
      const response = await fetch(`${this.host}/api/v1/chat.sendMessage`, {
        body: `{"message": { "rid": "${this.rid}", "msg": "${message}" }}`,
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": [REDACTED]"rc_token"),
          "X-User-Id": Cookies.get("rc_uid"),
        },
        method: "POST",
      });
      return await response.json();
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);

    }
  }

  async getUserInfo() {
    try {
      const response = await fetch(`${this.host}/api/v1/me`, {
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": [REDACTED]"rc_token"),
          "X-User-Id": Cookies.get("rc_uid"),
        },
        method: "GET",
      });
      return await response.json();
    } catch (err) {
      console.error(err.message);
      throw new Error(err.message);

    }
  }
}

import { createHash } from 'crypto';
export default function signoutkc(req,res){
    const [cookieCsrfToken,cookieCsrfTokenHash] =  req.cookies['next-auth.csrf-token'].split('|');
    const expectedCsrfTokenHash = createHash("sha256")
      .update(`${cookieCsrfToken}${process.env.NEXTAUTH_SECRET}`)
      .digest("hex");
    const redirectUri = req.query.callbackUrl? encodeURIComponent(req.query.callbackUrl) : process.env.NEXTAUTH_URL;
    if(cookieCsrfTokenHash === expectedCsrfTokenHash && cookieCsrfToken === req.query.token){
        res.redirect(`${process.env.KEYCLOAK_ISSUER}/protocol/openid-connect/logout?redirect_uri=${redirectUri}`);
    } else {
        res.statusCode = 401;
        res.end();
    }
}

export default async function profilekc(req,res){
    res.redirect(`${process.env.KEYCLOAK_ISSUER}/account`);
}

import axios from 'axios';
import qs from 'qs';
import urlJoin from 'url-join';

export default async function rocketChatCallback(req, res){
	const {
		grant_type,
		code,
		redirect_uri
	} = req.body;
	const client_id =  process.env.ROCKETCHAT_CLIENT_ID;
	const client_secret = [REDACTED];
	try {
		const result = await getTokenResultFromRocketChat({
			grant_type,
			code,
			client_id,
			client_secret,
			redirect_uri
		});

		if(result.status == 200){
			const data = {...result.data};
			if(data.token_type === 'bearer')
				data.token_type = 'Bearer';
			res.json(data);
		} else {
			res.statusCode = result.status; 
			res.headers['Cache-Control'] = 'no-cache'
			res.send(result.data);
			res.end();
		}
	} catch(e) {
		console.error(e);
		res.statusCode = 500;
		res.send('Unexpected Error.');
		res.end();
	}
}

const getTokenResultFromRocketChat = async ({
	code,
	redirect_uri,
	grant_type,
	client_id,
	client_secret
} = {}) => {
	var data = qs.stringify({
		code,
		redirect_uri,
		grant_type,
		client_id,
		client_secret
	});
	var config = {
		method: 'post',
		url: urlJoin(process.env.ROCKETCHAT_URL,'/oauth/token'),
		headers: { 
			'Content-Type': 'application/x-www-form-urlencoded'
		},
		data : data
	};

	try {
		return await axios(config);
	} catch(e) {
		if(e.response)
			return  e.response;
		else
			throw e;
	}
}

import NextAuth from "next-auth";
import KeyCloakProvider from "next-auth/providers/keycloak";
import { RocketChatOAuthProvider } from "../../../lib/auth/RocketChatOAuthProvider";
import { signCook } from "../../../lib/conferences/eventCall";

export default async function handleAuth(req, res) {
  return await NextAuth({
    providers: [
      KeyCloakProvider({
        clientId: process.env.KEYCLOAK_ID,
        clientSecret: [REDACTED],
        issuer: process.env.KEYCLOAK_ISSUER,
        profile(profile) {
          // profile -> returned from keycloak server.
          return {
            id: profile.sub,
            name: profile.name ?? profile.preferred_username,
            email: profile.email,
            image: profile.picture,
          };
        },
      }),
      RocketChatOAuthProvider({
        clientId: process.env.ROCKETCHAT_CLIENT_ID,
        clientSecret: [REDACTED],
        rocketChatUrl: process.env.ROCKETCHAT_URL,
      }),
    ],
    callbacks: {
      async jwt({ token, account, profile, session }) {
        // Called when generating our custom token
        // Persist the OAuth access_token to the token right after signin

        if (account) {
          token.accessToken = [REDACTED];
        }
        return token;
      },
      async session({ session, token }) {
        session.user.id = token.sub;
        session.user.sub = token.sub;
        session.user.image = token.picture;

        if (session.user?.email) {
          const hashmail = await signCook({ mail: session.user.email });
          const expTime = new Date(session.expires).toUTCString();
          res.setHeader("Set-Cookie", [
            "hashmail=" +
              hashmail.data.hash +
              "; expires=" +
              expTime +
              "; path=/",
          ]);
        }
        return session;
      },
    },
    events: {
      async signOut({ token }) {
        res.setHeader("Set-Cookie", [
          "hashmail=deleted; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT",
          "rc_uid=deleted; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT",
          "rc_token=deleted; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT",
        ]);
        return token;
      },
    },
  })(req, res);
}

import axios from "axios";

const eventUrl = process.env.NEXT_PUBLIC_EVENT_BACKEND_URL;

export default async function handler(req, res) {
  if (req.method === "PATCH") {
    try {
      const headers = {
        "Content-Type": "application/vnd.api+json",
        Authorization: `JWT ${req.body.auth}`,
      };

      const result = await axios.patch(
        `${eventUrl}/v1/users/${req.body.uid}`,
        req.body.data,
        {
          headers: headers,
        }
      );

      res.status(200).send(result.data);
    } catch (error) {
      res.status(error.response.status).send({ error: error.response.data.errors });
    }
    // Process a POST request
  } else {
    // Handle any other HTTP method
    res.status(405).json({ error: "Unsupported Route Method" });
  }
}

